SELECT id, order_id, LEAD(unit_price) OVER w_grp AS next_unit_price, LAG(quantity) OVER w_grp AS prev_quantity, LEAD(quantity) OVER w_grp AS next_quantity, ROW_NUMBER() OVER w_grp AS seq_no, CORR(quantity, unit_price) OVER (PARTITION BY order_id) AS corr_quantity_unit_price FROM order_items WHERE quantity > 4 WINDOW w_grp AS (PARTITION BY product_id, order_id ORDER BY unit_price, id);
